        assertEquals(
            "Digest username=\"Mufasa\", realm=\"$digestRealm\", nonce=\"$digestNonce\", uri=\"/dir/index.html\", " +
                "response=\"7b2cc3b30e75b4777ea31027084363fd\", opaque=\"$digestOpaque\"",
            withOpaque.authorization("GET", "/dir/index.html"),
        )
    }

