    @Test
    fun bhvAuthdigest706RefusesBadCredentialsAtConstructionAndMasksThePassword() {
        val secret = listOf("s3", "cret").joinToString("")
        val empty =
            assertThrows(IllegalArgumentException::class.java) {
                DigestAuthenticator("https://api.example.com", "", secret)
            }
        assertEquals("Digest username must not be empty", empty.message)
        val bad =
            listOf(
                "ali\rce" to secret,
                "ali\nce" to secret,
                "ali\u0000ce" to secret,
                "alice" to "s3\r$secret",
                "alice" to "s3\n$secret",
                "alice" to "s3\u0000$secret",
            )
        for ((user, pass) in bad) {
            val refused =
                assertThrows(IllegalArgumentException::class.java) {
                    DigestAuthenticator("https://api.example.com", user, pass)
                }
            assertEquals("Digest credentials must not contain a line break or NUL", refused.message)
        }
        val quote =
            assertThrows(IllegalArgumentException::class.java) {
                DigestAuthenticator("https://api.example.com", "ali\"ce", secret)
            }
        assertEquals("Digest username must not contain a double quote", quote.message)
        assertEquals(
            "DigestAuthenticator(host=https://api.example.com, username=alice, password=***)",
            DigestAuthenticator("https://api.example.com", "alice", secret).toString(),
        )
    }
